    const resolved = dir.replace(/^~/, HOME);
    return fs.existsSync(resolved) && fs.statSync(resolved).isDirectory();
  });

  config.projectDirs = validDirs;
  saveConfig(config);
  res.json({ ok: true, validated: validDirs.length, rejected: dirs.length - validDirs.length });
});
